a<-commandArgs(TRUE);P<-normalizePath(a[1]);W<-file.path(P,'work/2026-11-06-mutographs-country-bubbles');source(file.path(P,'biofigure/scripts/figure_style.R'));library(ggplot2);library(grid);font<-bf_font('Arial');q<-jsonlite::fromJSON(file.path(W,'metadata.json'));d<-read.csv(file.path(P,'results/plot_data',q$plot_data_files),check.names=FALSE);stopifnot(nrow(d)==627,sum(d[['q-value']]<.05)==11)
sigs<-unique(d$Signature);countries<-unique(d$Country);types<-c('SBS','DBS','ID','CN','SV');pitch<-(136-8)/57;offset<-c(0,cumsum(vapply(types,function(t)sum(startsWith(sigs,t)),integer(1))[-5]*pitch+2));names(offset)<-types
# Coordinates are final millimetres; five widths proportional to signature count.
d$x<-25+offset[d$variant_type]+(vapply(seq_len(nrow(d)),function(i)match(d$Signature[i],sigs[startsWith(sigs,d$variant_type[i])]),integer(1))-.5)*pitch;d$y<-80-(match(d$Country,countries)-.5)*4;d$point_size<-.65+1.9*sqrt(d$minus_log10_q/max(d$minus_log10_q));d$edge<-ifelse(d[['q-value']]<.05,'#243B4B','#D9E0E4');d$stroke<-ifelse(d[['q-value']]<.05,.35,.15)
ramp<-grDevices::colorRampPalette(c('#159F96','#FFFEFA','#E36A55'))(401);d$fill<-ramp[pmin(401,pmax(1,round((d$log2_OR+5)/10*400)+1))]
headers<-data.frame(xmin=25+offset,xmax=25+offset+vapply(types,function(t)sum(startsWith(sigs,t)),integer(1))*pitch,ymin=82,ymax=87,col='#EEF3F5');shades<-data.frame(xmin=25,xmax=161,ymin=seq(36,76,by=8),ymax=seq(40,80,by=8),col='#FAFBFC');bg<-rbind(headers,shades)
hlines<-data.frame(y=80-(seq(11)-.5)*4);vlines<-d[!duplicated(d$Signature),c('x','Signature')]
p<-ggplot()+geom_rect(data=bg,aes(xmin=xmin,xmax=xmax,ymin=ymin,ymax=ymax,fill=col),colour=NA)+geom_segment(data=hlines,aes(x=25,xend=161,y=y,yend=y),colour='#E6ECEF',linewidth=.18)+geom_segment(data=vlines,aes(x=x,xend=x,y=36,yend=80),colour='#EDF1F3',linewidth=.16)+geom_point(data=d,aes(x=x,y=y,size=point_size,fill=fill,colour=edge,stroke=stroke),shape=21,alpha=1)+scale_fill_identity()+scale_colour_identity()+scale_size_identity()+coord_cartesian(xlim=c(0,183),ylim=c(0,90),expand=FALSE,clip='on')+theme_void(base_family=font$family)+theme(plot.margin=margin(0,0,0,0),legend.position='none')
cb<-rectGrob(x=.5,y=(seq_along(ramp)-.5)/length(ramp),width=1,height=1.02/length(ramp),gp=gpar(fill=ramp,col=NA));p<-p+annotation_custom(cb,xmin=169,xmax=172,ymin=39,ymax=79)
z<-0:4;sizes<-.65+1.9*sqrt(z/max(d$minus_log10_q));leg<-data.frame(x=c(74,84,94,104,114,139,158),y=c(rep(12,5),12,12),size=c(sizes,1.7,1.7),fill=c(rep('#FFFFFF',5),'#F5CFC6','#F5CFC6'),edge=c(rep('#7A8C98',5),'#243B4B','#D9E0E4'),stroke=c(rep(.2,5),.35,.15))
p<-p+geom_point(data=leg,aes(x,y,size=size,fill=fill,colour=edge,stroke=stroke),shape=21,alpha=1)
add<-function(x,y,label,size=7,hjust=.5,angle=0,col='#344956',face='plain')data.frame(x,y,label,hjust,angle,size=size/ggplot2::.pt,col,face)
lab<-rbind(add(23,hlines$y,countries,hjust=1),add(vlines$x,34,vlines$Signature,hjust=1,angle=55),add((headers$xmin+headers$xmax)/2,84.5,types,size=8,face='bold'),add(170.5,84.5,'log2 OR'),add(174,c(39,59,79),c('-5','0','5'),hjust=0),add(53,12,'-log10(q)',hjust=1),add(c(74,84,94,104,114),7.5,as.character(z)),add(c(142,161),12,c('q < 0.05','q >= 0.05'),hjust=0))
p<-p+geom_text(data=lab,aes(x,y,label=label,size=size,hjust=hjust,angle=angle,colour=col,fontface=face),family=font$family)
saveRDS(p,file.path(W,'plot.rds'));write.csv(d,file.path(W,'bubble-geometry.csv'),row.names=FALSE);jsonlite::write_json(list(labels=unique(lab$label)),file.path(W,'text-manifest.json'),pretty=TRUE,auto_unbox=TRUE);ggsave(file.path(W,'preview.png'),p,width=183,height=90,units='mm',dpi=320,device=ragg::agg_png,bg='white');cat('Exploratorypreviewready\n')
